import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> log = List.of("INFO started", "ERROR disk unavailable", "WARN retrying", "ERROR request failed");
        long errors = log.stream().filter(line -> line.contains("ERROR")).peek(System.out::println).count();
        System.out.println("Error count: " + errors);
    }
}
